<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/unified_experience_v1100.php';require_once __DIR__.'/app/customer_utility_v1030.php';
$me=current_user();if(!$me){header('Location: /login.php?next='.rawurlencode('/service-leads-v1030.php'));exit;}$uid=(int)$me['id'];$biz=sk1030_my_business_ids($uid);$flash='';$error='';
try{if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();sk1030_save_offer((int)($_POST['request_id']??0),(int)($_POST['business_id']??0),$_POST);$flash='Offer saved.';}}catch(Throwable $e){$error=$e->getMessage();}
$rows=[];if($biz){$ph=implode(',',array_fill(0,count($biz),'?'));try{$sql="SELECT r.*,rr.business_id,rr.status route_status,o.price offer_price,o.message offer_message,o.status offer_status FROM customer_request_routes_v1030 rr JOIN customer_service_requests_v1030 r ON r.id=rr.request_id LEFT JOIN customer_request_offers_v1030 o ON o.request_id=r.id AND o.business_id=rr.business_id WHERE rr.tenant_id=? AND rr.business_id IN ($ph) AND r.status IN ('open','in_progress') ORDER BY r.id DESC LIMIT 100";$q=db()->prepare($sql);$q->execute(array_merge([sk1030_tid()],$biz));$rows=$q->fetchAll()?:[];}catch(Throwable $e){$error=$e->getMessage();}}
$csrf=csrf_token();?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business Leads — ShahkotPK</title><link rel="stylesheet" href="/assets/customer-utility-v1030.css?v=1030"><?php sk1100_public_assets();?></head><body><?php sk1100_render_public_header(true);?><main><section class="cu-public-hero compact"><div class="cu-shell"><span>BUSINESS LEADS</span><h1>Customer requests routed to your business</h1><p>Send a clear price and message. Customer contact details are shown only for requests routed to your business.</p></div></section><div class="cu-shell"><?php if($flash):?><div class="notice ok"><?=htmlspecialchars($flash,ENT_QUOTES)?></div><?php endif;?><?php if($error):?><div class="notice bad"><?=htmlspecialchars($error,ENT_QUOTES)?></div><?php endif;?><?php if(!$biz):?><div class="notice">No business owned by this account was found.</div><?php endif;?><div class="lead-list"><?php foreach($rows as $r):?><article><div><small>#<?=(int)$r['id']?> · <?=htmlspecialchars((string)$r['category_key'],ENT_QUOTES)?></small><h2><?=htmlspecialchars((string)$r['need_text'],ENT_QUOTES)?></h2><p><?=htmlspecialchars((string)($r['area']??''),ENT_QUOTES)?> · Budget <?=((float)$r['budget_min']>0?'PKR '.number_format((float)$r['budget_min']):'not specified')?><?php if((float)$r['budget_max']>0):?> – <?=number_format((float)$r['budget_max'])?><?php endif;?></p><p><b>Customer:</b> <?=htmlspecialchars((string)$r['contact_name'],ENT_QUOTES)?> · <a href="tel:<?=htmlspecialchars(preg_replace('/[^0-9+]/','',(string)$r['contact_phone']),ENT_QUOTES)?>"><?=htmlspecialchars((string)$r['contact_phone'],ENT_QUOTES)?></a></p></div><form method="post" class="public-form offer"><input type="hidden" name="_csrf" value="<?=htmlspecialchars($csrf,ENT_QUOTES)?>"><input type="hidden" name="request_id" value="<?=(int)$r['id']?>"><input type="hidden" name="business_id" value="<?=(int)$r['business_id']?>"><label>Offer price<input type="number" min="0" name="price" value="<?=htmlspecialchars((string)($r['offer_price']??''),ENT_QUOTES)?>"></label><label class="wide">Message<textarea name="message" rows="3" placeholder="Availability, expected time, warranty/service details…"><?=htmlspecialchars((string)($r['offer_message']??''),ENT_QUOTES)?></textarea></label><button class="wide">Send / Update Offer</button></form></article><?php endforeach;?><?php if(!$rows&&$biz):?><p class="muted">No open customer requests are currently routed to your business.</p><?php endif;?></div></div></main><?php sk1100_render_ai_widget('public');?> </body></html>
